document.addEventListener('DOMContentLoaded',()=>{const d=window.cvData;if(!d)return;const setTxt=(id,val)=>{const el=document.getElementById(id);if(el)el.innerHTML=val;};setTxt('lbl-contact',d.labels.contact);setTxt('lbl-languages',d.labels.languages);setTxt('lbl-soft',d.labels.softSkills);setTxt('lbl-tech',d.labels.techSkills);setTxt('lbl-profile',d.labels.profile);setTxt('lbl-education',d.labels.education);setTxt('lbl-projects',d.labels.projects);setTxt('lbl-stack',d.labels.stack);setTxt('cv-name',d.basics.name);setTxt('cv-role',d.basics.role);setTxt('cv-summary',d.basics.summary);const imgPath=window.Utils.getSmartPath(d.basics.imageName,'PROFILE');const imgDiv=document.getElementById('cv-image-div');if(imgDiv){imgDiv.style.backgroundImage='none';imgDiv.style.overflow='hidden';imgDiv.innerHTML=`
        <img src="${imgPath}" 
             alt="Profile" 
             style="width: 100%; height: 100%; object-fit: cover; transform: scale(3.5); transform-origin: 50% 18%;" 
             onerror="window.Utils.handleImgError(this)">
      `;}const contactContainer=document.getElementById('cv-contact-list');if(contactContainer&&d.contact){contactContainer.innerHTML='';d.contact.forEach((item)=>{const isCopy=item.link==='-';const contentHtml=isCopy?`<span class="contact-link copyable" onclick="window.Utils.copyText('${item.text}', this)" title="Click para copiar">${item.text}</span>`:`<a href="${item.link}" target="_blank" class="contact-link">${item.text}</a>`;contactContainer.innerHTML+=`
          <div class="contact-item">
            <i data-lucide="${item.icon}" class="contact-icon"></i>
            ${contentHtml}
          </div>`;});}const langContainer=document.getElementById('cv-languages-list');d.languages.forEach((lang)=>{let percent=lang.percent;let label=lang.level;if(!percent&&lang.score&&lang.maxScore){percent=(lang.score/lang.maxScore)*100;if(lang.levelRanges){const found=lang.levelRanges.find((r)=>lang.score<=r.limit);if(found)label=`${found.code} ${found.label}`;}}langContainer.innerHTML+=`
      <div class="skill-row">
        <div class="skill-txt"><span>${lang.name}</span> <span>${label || ''}</span></div>
        <div class="progress-track">
           <div class="progress-fill" style="width: ${percent}%"></div>
           ${percent < 100 ? `<div class="progress-marker" style="left: ${percent}%"></div>` : ''}
        </div>
      </div>`;});const renderBars=(items,containerId)=>{const container=document.getElementById(containerId);if(!items||!container)return;items.forEach((skill)=>{container.innerHTML+=`
        <div class="skill-row">
          <div class="skill-txt"><span>${skill.name}</span></div>
          <div class="progress-track"><div class="progress-fill" style="width: ${skill.percent}%"></div></div>
        </div>`;});};renderBars(d.skills.soft,'cv-soft-skills');renderBars(d.skills.tech,'cv-tech-skills');const eduContainer=document.getElementById('cv-education-list');d.education.forEach((edu)=>{eduContainer.innerHTML+=`
      <div class="list-group">
        <div class="li-head">${edu.title} <span style="opacity:0.6; margin-left:5px; font-size:0.9em">${
          edu.date
        }</span></div>
        <div class="li-item">${edu.degree}</div>
        ${edu.desc ? `<div class="li-item">${edu.desc}</div>` : ''}
      </div>`;});const projContainer=document.getElementById('cv-projects-list');d.projects.forEach((proj)=>{projContainer.innerHTML+=`
      <div class="list-group">
        <div class="li-head">
          <span>${proj.title}</span>
          <span style="font-size:0.8em; opacity:0.8; font-weight:400; color:#444;">// ${proj.stack}</span>
        </div>
        <div class="li-item">${proj.desc}</div>
      </div>`;});const softContainer=document.getElementById('cv-software-grid');if(softContainer&&d.software){softContainer.innerHTML='';const iconsBase=d.config&&d.config.iconsPath?d.config.iconsPath:'../assets/icons/';d.software.forEach((soft)=>{let iconHTML='';if(soft.iconType==='local'){const fullPath=`${iconsBase}${soft.iconName}`;iconHTML=`<img src="${fullPath}" alt="${soft.name}" class="soft-icon local-img" loading="lazy" onerror="this.style.display='none'">`;}else if(soft.iconType==='lucide'){const color=soft.color||'#111';iconHTML=`<i data-lucide="${soft.iconName}" class="soft-icon" style="color:${color}"></i>`;}else{iconHTML=`<i class="${soft.iconClass} soft-icon"></i>`;}softContainer.innerHTML+=`
        <div class="soft-box">
          ${iconHTML}
          <span class="soft-name">${soft.name}</span>
        </div>`;});if(window.Utils&&window.Utils.initIcons){window.Utils.initIcons();}}window.Utils.initIcons();});